class Solution {
public:
    typedef long long ll;
    bool valid(vector<int> nums,ll mid,int tt)
    {
        ll sum=0;
        for(auto it:nums)
            sum+=mid/it;
        return sum>=tt;
    }
    long long minimumTime(vector<int>& time, int tt) {
        ll low=1;
        ll high=1LL* *max_element(time.begin(),time.end())*tt;
        while(low<high)
        {
            ll mid=low+(high-low)/2LL;
            if(valid(time,mid,tt))
                high=mid;
            else
                low=mid+1;
        }
        return low;
    }
};

class Solution:
    def minimumTime(self, time: List[int], totalTrips: int) -> int:
        left, right = 1, totalTrips * time[0]
        while left < right:
            mid = (left + right) // 2
            cur_sum = 0
            for t in time:
                cur_sum += mid // t
            if cur_sum >= totalTrips:
                right = mid
            else:
                left = mid + 1
